<?php $title='Upload-Richtlinien';$types=['jpg'=>'JPG','jpeg'=>'JPEG','png'=>'PNG','pdf'=>'PDF','docx'=>'DOCX'];$modules=['dutybook'=>'Dienstbuch','special_report'=>'Sonderberichte','valuables'=>'Wertsachen','house_bans'=>'Hausverbote','messages'=>'Mitteilungen']; ?>
<div class="page-header"><div><p class="eyebrow">Administration · Sicherheit</p><h1>Upload-Richtlinien</h1><p>Dateigröße und zulässige Typen werden serverseitig erzwungen. MIME-Type und Dateiendung müssen übereinstimmen.</p></div></div>
<form method="post" action="<?= e(url('admin/settings/uploads')) ?>" class="panel stack-form"><?= csrf_field() ?><label>Maximale Dateigröße pro Anhang (MB)<input type="number" min="1" max="100" name="max_mb" value="<?= (int)$settings['max_mb'] ?>" required></label>
<?php foreach($modules as $key=>$label):?><fieldset class="checkbox-panel"><legend><?= e($label) ?></legend><div class="checkbox-stack"><?php foreach($types as $ext=>$name):if(in_array($key,['valuables','house_bans','messages'],true)&&$ext==='docx')continue;?><label class="check-row"><input type="checkbox" name="<?= e($key) ?>[]" value="<?= e($ext) ?>" <?= in_array($ext,$settings[$key],true)?'checked':'' ?>><span><?= e($name) ?></span></label><?php endforeach;?></div></fieldset><?php endforeach;?>
<button class="button primary" type="submit">Upload-Richtlinien speichern</button></form>
